{'code': "from qgis.utils import plugins
mmqgis = plugins.get('mmqgis')
menu = mmqgis.mmqgis_menu
act = None
for a in menu.actions():
    m = a.menu()
    if m is not None and 'animate' in (a.text() or '').lower():
        for sa in m.actions():
            if (sa.text() or '') == 'Animate Zoom and Pan':
                act = sa
result = {
    'action_text': act.text() if act else None,
    'action_enabled': act.isEnabled() if act else None,
    'action_visible': act.isVisible() if act else None,
    'menu_enabled': menu.menuAction().isEnabled(),
}"}
